2972 as currently written:
```js
// transaction - using SSZ-compatible format so we don't have to decode-extract-encode in order to validate signature
0x00 || yParity || r || s || 0x65000000 || rlp(nonce, gasPrice, gasLimit, to, value, data)
// which is identical to
0x00 || ssz([yParity, r, s, rlp(nonce, gasPrice, gasLimit, to, value, data)])
// which is identical to
ssz([0x00, yParity, r, s, rlp(nonce, gasPrice, gasLimit, to, value, data)])

// receipt - SSZ encoded
0 || status || cumulativeGasUsed || logsBloom || 0x09010000 || ssz(logs)
// which is identical to
0 || ssz([status, cumulativeGasUsed, logsBloom, logs])
// which is identical to
ssz([0, status, cumulativeGasUsed, logsBloom, logs])
```
